/* Core-owned navigation and permission bootstrap for LAOO_TIME attendance periods. */
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRY
BEGIN TRANSACTION;
DECLARE @TimeProjectID bigint=(SELECT ProjectID FROM dbo.TDADProject WHERE ProjectCode=N'LAOO_TIME' AND IsActive=1);
IF @TimeProjectID IS NULL THROW 52800,N'Active LAOO_TIME project is required.',1;
DECLARE @Menus TABLE(MenuCode char(5) PRIMARY KEY,MenuGroupCode char(2),MenuName nvarchar(150),ScreenType int,RouteName nvarchar(150),RoutePath nvarchar(300),FeatureCode nvarchar(100),IconName nvarchar(100),SortOrder int);
INSERT @Menus VALUES
(N'29001',N'29',NCHAR(3619)+NCHAR(3641)+NCHAR(3611)+NCHAR(3649)+NCHAR(3610)+NCHAR(3610)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),1,N'timeAttendancePeriodSchemes',N'/company/time-attendance-period-schemes',N'TIME_ATTENDANCE_PERIOD_SCHEMES',N'calendar_month_outlined',10),
(N'29002',N'29',NCHAR(3612)+NCHAR(3641)+NCHAR(3585)+NCHAR(3614)+NCHAR(3609)+NCHAR(3633)+NCHAR(3585)+NCHAR(3591)+NCHAR(3634)+NCHAR(3609)+NCHAR(3585)+NCHAR(3633)+NCHAR(3610)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),4,N'timeAttendancePeriodAssignments',N'/company/time-attendance-period-assignments',N'TIME_ATTENDANCE_PERIOD_ASSIGNMENTS',N'person_add_alt_outlined',20),
(N'29003',N'29',NCHAR(3605)+NCHAR(3619)+NCHAR(3623)+NCHAR(3592)+NCHAR(3626)+NCHAR(3629)+NCHAR(3610)+NCHAR(3649)+NCHAR(3621)+NCHAR(3632)+NCHAR(3611)+NCHAR(3636)+NCHAR(3604)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),3,N'timeAttendancePeriods',N'/company/time-attendance-periods',N'TIME_ATTENDANCE_PERIODS',N'lock_clock_outlined',30);
IF EXISTS(SELECT 1 FROM @Menus S JOIN dbo.TDADMainMenu T ON T.MenuCode=S.MenuCode WHERE T.ScreenType<>S.ScreenType OR ISNULL(T.RouteName,N'')<>S.RouteName OR ISNULL(T.RoutePath,N'')<>S.RoutePath) THROW 52801,N'Time attendance period MenuCode conflicts with ScreenType or route.',1;
IF EXISTS(SELECT 1 FROM @Menus S JOIN dbo.TDADMainMenu T ON (T.RouteName=S.RouteName OR T.RoutePath=S.RoutePath) AND T.MenuCode<>S.MenuCode) THROW 52802,N'Time attendance period RouteName or RoutePath is already used.',1;
UPDATE dbo.TDADMenuGroup SET MenuGroupName=NCHAR(3611)+NCHAR(3636)+NCHAR(3604)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3649)+NCHAR(3621)+NCHAR(3632)+NCHAR(3619)+NCHAR(3634)+NCHAR(3618)+NCHAR(3591)+NCHAR(3634)+NCHAR(3609)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),IsActive=1,UpdateDate=SYSUTCDATETIME() WHERE MenuGroupCode=N'29';
IF NOT EXISTS(SELECT 1 FROM dbo.TDADMenuGroup WHERE MenuGroupCode=N'29')
INSERT dbo.TDADMenuGroup(AudienceType,MenuGroupCode,MenuGroupName,IconName,SortOrder,IsExpandedDefault,IsActive,CreateDate,ShowPermissionPoint,OpenOption) VALUES(N'C',N'29',NCHAR(3611)+NCHAR(3636)+NCHAR(3604)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3649)+NCHAR(3621)+NCHAR(3632)+NCHAR(3619)+NCHAR(3634)+NCHAR(3618)+NCHAR(3591)+NCHAR(3634)+NCHAR(3609)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),N'event_available_outlined',270,0,1,SYSUTCDATETIME(),0,0);
UPDATE T SET T.MenuGroupCode=S.MenuGroupCode,T.MenuName=S.MenuName,T.ScreenType=S.ScreenType,T.RouteName=S.RouteName,T.RoutePath=S.RoutePath,T.FeatureCode=S.FeatureCode,T.IconName=S.IconName,T.SortOrder=S.SortOrder,T.IsVisible=1,T.IsFavoriteAllowed=1,T.IsActive=1,T.ShowPermissionPoint=0,T.UpdateDate=SYSUTCDATETIME() FROM dbo.TDADMainMenu T JOIN @Menus S ON S.MenuCode=T.MenuCode;
INSERT dbo.TDADMainMenu(MenuCode,MenuGroupCode,MenuName,ScreenType,RouteName,RoutePath,FeatureCode,IconName,SortOrder,IsVisible,IsFavoriteAllowed,IsActive,CreateDate,ShowPermissionPoint)
SELECT S.MenuCode,S.MenuGroupCode,S.MenuName,S.ScreenType,S.RouteName,S.RoutePath,S.FeatureCode,S.IconName,S.SortOrder,1,1,1,SYSUTCDATETIME(),0 FROM @Menus S WHERE NOT EXISTS(SELECT 1 FROM dbo.TDADMainMenu T WHERE T.MenuCode=S.MenuCode);
UPDATE dbo.TDADProjectMenuGroup SET SortOrder=5,IsActive=1,UpdateDate=SYSUTCDATETIME() WHERE ProjectID=@TimeProjectID AND MenuGroupCode=N'29';
IF NOT EXISTS(SELECT 1 FROM dbo.TDADProjectMenuGroup WHERE ProjectID=@TimeProjectID AND MenuGroupCode=N'29') INSERT dbo.TDADProjectMenuGroup(ProjectID,MenuGroupCode,SortOrder,IsActive,CreateDate) VALUES(@TimeProjectID,N'29',5,1,SYSUTCDATETIME());
UPDATE T SET T.MenuGroupCode=S.MenuGroupCode,T.SortOrder=S.SortOrder,T.IsActive=1,T.UpdateDate=SYSUTCDATETIME() FROM dbo.TDADProjectMenu T JOIN @Menus S ON S.MenuCode=T.MenuCode WHERE T.ProjectID=@TimeProjectID;
INSERT dbo.TDADProjectMenu(ProjectID,MenuCode,MenuGroupCode,SortOrder,IsActive,CreateDate) SELECT @TimeProjectID,S.MenuCode,S.MenuGroupCode,S.SortOrder,1,SYSUTCDATETIME() FROM @Menus S WHERE NOT EXISTS(SELECT 1 FROM dbo.TDADProjectMenu T WHERE T.ProjectID=@TimeProjectID AND T.MenuCode=S.MenuCode);
UPDATE dbo.TDADProjectMenu SET IsActive=0,UpdateDate=SYSUTCDATETIME() WHERE MenuCode IN(SELECT MenuCode FROM @Menus) AND ProjectID<>@TimeProjectID AND IsActive=1;
DECLARE @Permissions TABLE(ScreenCode nvarchar(50),ScreenNameTH nvarchar(200),ScreenNameEN nvarchar(200),ActionCode nvarchar(50),ActionNameTH nvarchar(200),ActionNameEN nvarchar(200),PRIMARY KEY(ScreenCode,ActionCode));
INSERT @Permissions VALUES
(N'29001',NCHAR(3619)+NCHAR(3641)+NCHAR(3611)+NCHAR(3649)+NCHAR(3610)+NCHAR(3610)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),N'Attendance period schemes',N'VIEW',NCHAR(3604)+NCHAR(3641)+NCHAR(3586)+NCHAR(3657)+NCHAR(3629)+NCHAR(3617)+NCHAR(3641)+NCHAR(3621),N'View'),(N'29001',NCHAR(3619)+NCHAR(3641)+NCHAR(3611)+NCHAR(3649)+NCHAR(3610)+NCHAR(3610)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),N'Attendance period schemes',N'CREATE',NCHAR(3648)+NCHAR(3614)+NCHAR(3636)+NCHAR(3656)+NCHAR(3617)+NCHAR(3586)+NCHAR(3657)+NCHAR(3629)+NCHAR(3617)+NCHAR(3641)+NCHAR(3621),N'Create'),(N'29001',NCHAR(3619)+NCHAR(3641)+NCHAR(3611)+NCHAR(3649)+NCHAR(3610)+NCHAR(3610)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),N'Attendance period schemes',N'EDIT',NCHAR(3649)+NCHAR(3585)+NCHAR(3657)+NCHAR(3652)+NCHAR(3586)+NCHAR(3586)+NCHAR(3657)+NCHAR(3629)+NCHAR(3617)+NCHAR(3641)+NCHAR(3621),N'Edit'),(N'29001',NCHAR(3619)+NCHAR(3641)+NCHAR(3611)+NCHAR(3649)+NCHAR(3610)+NCHAR(3610)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),N'Attendance period schemes',N'DELETE',NCHAR(3621)+NCHAR(3610)+NCHAR(3586)+NCHAR(3657)+NCHAR(3629)+NCHAR(3617)+NCHAR(3641)+NCHAR(3621),N'Delete'),
(N'29002',NCHAR(3612)+NCHAR(3641)+NCHAR(3585)+NCHAR(3614)+NCHAR(3609)+NCHAR(3633)+NCHAR(3585)+NCHAR(3591)+NCHAR(3634)+NCHAR(3609)+NCHAR(3585)+NCHAR(3633)+NCHAR(3610)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),N'Attendance period assignments',N'VIEW',NCHAR(3604)+NCHAR(3641)+NCHAR(3586)+NCHAR(3657)+NCHAR(3629)+NCHAR(3617)+NCHAR(3641)+NCHAR(3621),N'View'),(N'29002',NCHAR(3612)+NCHAR(3641)+NCHAR(3585)+NCHAR(3614)+NCHAR(3609)+NCHAR(3633)+NCHAR(3585)+NCHAR(3591)+NCHAR(3634)+NCHAR(3609)+NCHAR(3585)+NCHAR(3633)+NCHAR(3610)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),N'Attendance period assignments',N'CREATE',NCHAR(3648)+NCHAR(3614)+NCHAR(3636)+NCHAR(3656)+NCHAR(3617)+NCHAR(3586)+NCHAR(3657)+NCHAR(3629)+NCHAR(3617)+NCHAR(3641)+NCHAR(3621),N'Create'),(N'29002',NCHAR(3612)+NCHAR(3641)+NCHAR(3585)+NCHAR(3614)+NCHAR(3609)+NCHAR(3633)+NCHAR(3585)+NCHAR(3591)+NCHAR(3634)+NCHAR(3609)+NCHAR(3585)+NCHAR(3633)+NCHAR(3610)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),N'Attendance period assignments',N'EDIT',NCHAR(3649)+NCHAR(3585)+NCHAR(3657)+NCHAR(3652)+NCHAR(3586)+NCHAR(3586)+NCHAR(3657)+NCHAR(3629)+NCHAR(3617)+NCHAR(3641)+NCHAR(3621),N'Edit'),
(N'29003',NCHAR(3605)+NCHAR(3619)+NCHAR(3623)+NCHAR(3592)+NCHAR(3626)+NCHAR(3629)+NCHAR(3610)+NCHAR(3649)+NCHAR(3621)+NCHAR(3632)+NCHAR(3611)+NCHAR(3636)+NCHAR(3604)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),N'Attendance periods',N'VIEW',NCHAR(3604)+NCHAR(3641)+NCHAR(3586)+NCHAR(3657)+NCHAR(3629)+NCHAR(3617)+NCHAR(3641)+NCHAR(3621),N'View'),(N'29003',NCHAR(3605)+NCHAR(3619)+NCHAR(3623)+NCHAR(3592)+NCHAR(3626)+NCHAR(3629)+NCHAR(3610)+NCHAR(3649)+NCHAR(3621)+NCHAR(3632)+NCHAR(3611)+NCHAR(3636)+NCHAR(3604)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),N'Attendance periods',N'APPROVE',NCHAR(3629)+NCHAR(3609)+NCHAR(3640)+NCHAR(3617)+NCHAR(3633)+NCHAR(3605)+NCHAR(3636),N'Approve'),(N'29003',NCHAR(3605)+NCHAR(3619)+NCHAR(3623)+NCHAR(3592)+NCHAR(3626)+NCHAR(3629)+NCHAR(3610)+NCHAR(3649)+NCHAR(3621)+NCHAR(3632)+NCHAR(3611)+NCHAR(3636)+NCHAR(3604)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),N'Attendance periods',N'FINALIZE',NCHAR(3611)+NCHAR(3636)+NCHAR(3604)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604),N'Finalize'),(N'29003',NCHAR(3605)+NCHAR(3619)+NCHAR(3623)+NCHAR(3592)+NCHAR(3626)+NCHAR(3629)+NCHAR(3610)+NCHAR(3649)+NCHAR(3621)+NCHAR(3632)+NCHAR(3611)+NCHAR(3636)+NCHAR(3604)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3621)+NCHAR(3591)+NCHAR(3648)+NCHAR(3623)+NCHAR(3621)+NCHAR(3634),N'Attendance periods',N'REOPEN',NCHAR(3648)+NCHAR(3611)+NCHAR(3636)+NCHAR(3604)+NCHAR(3591)+NCHAR(3623)+NCHAR(3604)+NCHAR(3629)+NCHAR(3637)+NCHAR(3585)+NCHAR(3588)+NCHAR(3619)+NCHAR(3633)+NCHAR(3657)+NCHAR(3591),N'Reopen');
UPDATE T SET T.ScreenNameTH=S.ScreenNameTH,T.ScreenNameEN=S.ScreenNameEN,T.ActionNameTH=S.ActionNameTH,T.ActionNameEN=S.ActionNameEN,T.IsActive=1 FROM dbo.TDADPermission T JOIN @Permissions S ON S.ScreenCode=T.ScreenCode AND S.ActionCode=T.ActionCode WHERE T.ProjectID=@TimeProjectID;
UPDATE T SET T.IsActive=0 FROM dbo.TDADPermission T JOIN @Menus M ON M.MenuCode=T.ScreenCode LEFT JOIN @Permissions S ON S.ScreenCode=T.ScreenCode AND S.ActionCode=T.ActionCode WHERE T.ProjectID=@TimeProjectID AND S.ScreenCode IS NULL;
INSERT dbo.TDADPermission(ProjectID,ScreenCode,ScreenNameTH,ScreenNameEN,ActionCode,ActionNameTH,ActionNameEN,IsActive,CreatedDate)
SELECT @TimeProjectID,S.ScreenCode,S.ScreenNameTH,S.ScreenNameEN,S.ActionCode,S.ActionNameTH,S.ActionNameEN,1,SYSUTCDATETIME() FROM @Permissions S WHERE NOT EXISTS(SELECT 1 FROM dbo.TDADPermission T WHERE T.ProjectID=@TimeProjectID AND T.ScreenCode=S.ScreenCode AND T.ActionCode=S.ActionCode);
COMMIT TRANSACTION;
END TRY
BEGIN CATCH
IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
THROW;
END CATCH;
